import { Component, input } from '@angular/core';
import { TablerIconComponent } from '@tabler/icons-angular';

/** hrm-media-cell — ô "logo/biểu tượng + nhãn": ảnh logo hoặc icon trong khung vuông + tên + dòng phụ.
 *  Dùng cho cột dự án/công ty/tài sản. src ưu tiên; không có thì dùng icon Tabler. */
@Component({
  selector: 'hrm-media-cell',
  imports: [TablerIconComponent],
  template: `
    <span class="mc-media" [attr.data-shape]="shape()">
      @if (src()) {
        <img [src]="src()" [alt]="label()" />
      } @else if (icon()) {
        <tabler-icon [icon]="$any(icon())" [size]="18" />
      }
    </span>
    <span class="mc-body">
      <span class="mc-label">{{ label() }}</span>
      @if (sub()) { <span class="mc-sub">{{ sub() }}</span> }
    </span>
  `,
  host: { class: 'hrm-media-cell' },
  styles: [`
:host { display: inline-flex; align-items: center; gap: 10px; min-width: 0; max-width: 100%; }
.mc-media { flex: none; width: 32px; height: 32px; display: grid; place-items: center;
  background: var(--bg-surface-subtle); color: var(--icon-secondary); overflow: hidden; }
.mc-media[data-shape='square'] { border-radius: var(--radius-md); }
.mc-media[data-shape='circle'] { border-radius: var(--radius-full); }
.mc-media img { width: 100%; height: 100%; object-fit: cover; }
.mc-body { display: flex; flex-direction: column; min-width: 0; }
.mc-label { font-size: var(--fs-14); color: var(--text-strong); line-height: 1.35;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.mc-sub { font-size: var(--fs-12); color: var(--text-sub); line-height: 1.3;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  `],
})
export class HrmMediaCell {
  readonly src = input('');
  readonly icon = input<unknown>(null);
  readonly label = input('');
  readonly sub = input('');
  readonly shape = input<'square' | 'circle'>('square');
}
